import { Page } from './types';
import { TemplateEngine } from './templates';

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export function generatePageHtml(page: Page, engine?: TemplateEngine): string {
  if (engine) {
    return engine.renderPage(page);
  }

  const { title, date, tags } = page.frontmatter;
  const dateStr = date || '';
  const tagsStr = tags ? tags.map((t) => escapeHtml(t)).join(', ') : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
  </header>
  <main>
    <article>
      <h1>${escapeHtml(title)}</h1>
      ${dateStr ? `<time datetime="${escapeHtml(dateStr)}">${escapeHtml(dateStr)}</time>` : ''}
      ${tagsStr ? `<p>Tags: ${tagsStr}</p>` : ''}
      <div>${page.html}</div>
    </article>
  </main>
</body>
</html>`;
}

export function generateIndexHtml(pages: Page[], engine?: TemplateEngine): string {
  if (engine) {
    return engine.renderIndex(pages);
  }

  const items = pages
    .map((page) => {
      const { title, date, tags } = page.frontmatter;
      const dateStr = date || '';
      const tagsStr = tags ? tags.map((t) => escapeHtml(t)).join(', ') : '';

      return `      <li>
        <a href="${escapeHtml(page.slug)}.html">${escapeHtml(title)}</a>
        ${dateStr ? `<span>${escapeHtml(dateStr)}</span>` : ''}
        ${tagsStr ? `<span>Tags: ${tagsStr}</span>` : ''}
      </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Index</title>
</head>
<body>
  <header>
    <h1>All Pages</h1>
  </header>
  <main>
    <ul>
${items}
    </ul>
  </main>
</body>
</html>`;
}

import fs from 'fs';
import path from 'path';
import { parseMarkdownDirectory } from './parser';
import { generatePageHtml, generateIndexHtml } from './generator';
import { TemplateEngine } from './templates';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
}

export function build(options: BuildOptions): void {
  const { contentDir, outputDir, templatesDir } = options;

  const pages = parseMarkdownDirectory(contentDir);

  let engine: TemplateEngine | undefined;
  if (templatesDir) {
    engine = new TemplateEngine();
    engine.init(templatesDir);
  }

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const html = generatePageHtml(page, engine);
    const outPath = path.join(outputDir, `${page.slug}.html`);
    fs.writeFileSync(outPath, html, 'utf-8');
  }

  const indexHtml = generateIndexHtml(pages, engine);
  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, indexHtml, 'utf-8');
}

#!/usr/bin/env node
import { Command } from 'commander';
import path from 'path';
import { build } from './build';

const program = new Command();

program
  .name('ssg')
  .description('A static site generator')
  .version('1.0.0');

program
  .command('build')
  .description('Build the static site')
  .option('--content <dir>', 'Content directory', './content')
  .option('--output <dir>', 'Output directory', './dist')
  .option('--templates <dir>', 'Templates directory')
  .action((options) => {
    const contentDir = path.resolve(options.content);
    const outputDir = path.resolve(options.output);
    const templatesDir = options.templates ? path.resolve(options.templates) : undefined;
    build({ contentDir, outputDir, templatesDir });
  });

program.parse(process.argv);

